INSERT INTO notices (id,title,body,posted_by,created_at) VALUES
(1,'Mid-term Exam Schedule Published','The Fall 2026 mid-term exam schedule is now available on the portal.',14,'2026-10-30 10:00:00'),
(2,'Winter Break Notice','The university will remain closed during the winter break as per the academic calendar.',7,'2026-10-05 10:00:00'),
(3,'Fee Payment Deadline','Last date for semester fee payment is 30 November 2026.',29,'2026-11-10 10:00:00'),
(4,'Library Opening Hours Updated','The library will remain open from 8 AM to 8 PM on working days.',20,'2026-11-01 10:00:00'),
(5,'Course Registration for Spring 2027','Registration opens in the first week of December.',28,'2026-11-05 10:00:00'),
(6,'Result Publication Notice','Spring 2026 results have been published.',30,'2026-10-07 10:00:00'),
(7,'Convocation 2026 Registration','Eligible students should register for convocation by 15 December.',14,'2026-10-21 10:00:00'),
(8,'Class Cancelled Due to Weather','Classes on the affected day are rescheduled.',22,'2026-10-22 10:00:00'),
(9,'Annual Sports Week','Annual sports week begins next month. Register at the student affairs office.',27,'2026-11-15 10:00:00'),
(10,'Scholarship Applications Open','Merit and need based scholarship applications are open.',29,'2026-10-12 10:00:00'),
(11,'Campus Maintenance Notice','Some classrooms will be unavailable for maintenance this weekend.',14,'2026-11-01 10:00:00'),
(12,'Department Seminar Series','Departments will hold seminars every Thursday.',12,'2026-10-15 10:00:00');
